def get_fci_standard_url(fci_number):
    """Return the official FCI standard URL for a given breed number."""
    slug = FCI_URL_SLUGS.get(fci_number)
    if slug:
        return f'https://www.fci.be/en/nomenclature/{slug}-{fci_number}.html'
    return None


def get_breed_data():
    """Return the complete breed data dictionary."""
    return BREED_DATA
